changeSet.sql:
create table splitwise.groups ( id_pk bigint not null, created timestamp(6), deleted timestamp(6), updated timestamp(6), creator_id_fk bigint, description varchar(100) not null, name varchar(50) not null, primary key (id_pk) );
create sequence splitwise.groups_sequence start with 1 increment by 50;
alter table if exists splitwise.groups add constraint FK5llh2oxwb9l473bh1v1nrvjje foreign key (creator_id_fk) references splitwise.users;
create table splitwise.user_group ( group_id_fk bigint not null, user_id_fk bigint not null, primary key (group_id_fk, user_id_fk) );
alter table if exists splitwise.user_group add constraint FK9n9in7sor101yij5ue03jyh7f foreign key (user_id_fk) references splitwise.users;
alter table if exists splitwise.user_group add constraint FK4ejcgd5ytm6grsljumynkt06l foreign key (group_id_fk) references splitwise.groups;

create table splitwise.group_invites ( id_pk bigint not null, created timestamp(6), deleted timestamp(6), updated timestamp(6), accepted boolean, group_id_fk bigint, invited_id_fk bigint, inviter_id_fk bigint, primary key (id_pk) );
create sequence splitwise.group_invites_sequence start with 1 increment by 50;
alter table if exists splitwise.group_invites add constraint FKfjnqryvwc5mtw00jacuipglj6 foreign key (group_id_fk) references splitwise.groups;
alter table if exists splitwise.group_invites add constraint FKhjhk1el9mbvrsyqgmg8mo0lvu foreign key (invited_id_fk) references splitwise.users;
alter table if exists splitwise.group_invites add constraint FK6vsyspjmf2i43a49iupogndfw foreign key (inviter_id_fk) references splitwise.users;

create table splitwise.costs ( id_pk bigint not null, created timestamp(6), deleted timestamp(6), updated timestamp(6), amount numeric(38, 2), creator_id_fk bigint, description varchar(200), group_id_fk bigint, settled boolean default false, title varchar(100), primary key (id_pk) );
create table splitwise.user_costs ( cost_id_fk bigint not null, user_id_fk bigint not null, primary key (cost_id_fk, user_id_fk) );
create sequence splitwise.costs_sequence start with 1 increment by 50;
alter table if exists splitwise.costs add constraint FKsus7aurlvq80kl87woepo9sbs foreign key (creator_id_fk) references splitwise.users;
alter table if exists splitwise.costs add constraint FKghpvwxkvkd76wv7kh1xh57phu foreign key (group_id_fk) references splitwise.groups;
alter table if exists splitwise.user_costs add constraint FKfr11huka1a5pauysx62td6gx3 foreign key (user_id_fk) references splitwise.users;
alter table if exists splitwise.user_costs add constraint FKob4wqxskr24in5220ctos0mvw foreign key (cost_id_fk) references splitwise.costs;

create table splitwise.cost_documents ( id_pk bigint not null, created timestamp(6), deleted timestamp(6), updated timestamp(6), amount numeric(38, 2), cost_id_fk bigint, creditor_id_fk bigint, debtor_id_fk bigint, group_id_fk bigint, primary key (id_pk) );
create sequence splitwise.cost_documents_sequence start with 1 increment by 50;
alter table if exists splitwise.cost_documents add constraint FKpvm2y4nflgr819c16dnjfqumk foreign key (cost_id_fk) references splitwise.costs;
alter table if exists splitwise.cost_documents add constraint FKgkic8cpx1qbtd65wxgrdh0b1x foreign key (creditor_id_fk) references splitwise.users;
alter table if exists splitwise.cost_documents add constraint FK1hjq3g78fydcj59rcm6a0b30v foreign key (debtor_id_fk) references splitwise.users;
alter table if exists splitwise.cost_documents add constraint FKhl12u3n2hoyw2infa3gc5y3oa foreign key (group_id_fk) references splitwise.groups;
